DO $cubingapp_roux_pyraminx_counts$
DECLARE got BIGINT;
BEGIN
  SELECT COUNT(*) INTO got FROM alg_cases WHERE puzzle = '3x3' AND set_slug = '2-look-cmll';
  IF got <> 9 THEN RAISE EXCEPTION '3x3/2-look-cmll: expected 9 cases, got %', got; END IF;
  SELECT COALESCE(SUM((SELECT SUM(jsonb_array_length(orientation.value)) FROM jsonb_array_elements(algs) AS orientation(value))), 0) INTO got FROM alg_cases WHERE puzzle = '3x3' AND set_slug = '2-look-cmll';
  IF got <> 9 THEN RAISE EXCEPTION '3x3/2-look-cmll: expected 9 algorithms, got %', got; END IF;
  SELECT COUNT(*) INTO got FROM alg_cases WHERE puzzle = '3x3' AND set_slug = 'cmll';
  IF got <> 42 THEN RAISE EXCEPTION '3x3/cmll: expected 42 cases, got %', got; END IF;
  SELECT COALESCE(SUM((SELECT SUM(jsonb_array_length(orientation.value)) FROM jsonb_array_elements(algs) AS orientation(value))), 0) INTO got FROM alg_cases WHERE puzzle = '3x3' AND set_slug = 'cmll';
  IF got <> 179 THEN RAISE EXCEPTION '3x3/cmll: expected 179 algorithms, got %', got; END IF;
  SELECT COUNT(*) INTO got FROM alg_cases WHERE puzzle = '3x3' AND set_slug = 'oh-cmll';
  IF got <> 42 THEN RAISE EXCEPTION '3x3/oh-cmll: expected 42 cases, got %', got; END IF;
  SELECT COALESCE(SUM((SELECT SUM(jsonb_array_length(orientation.value)) FROM jsonb_array_elements(algs) AS orientation(value))), 0) INTO got FROM alg_cases WHERE puzzle = '3x3' AND set_slug = 'oh-cmll';
  IF got <> 99 THEN RAISE EXCEPTION '3x3/oh-cmll: expected 99 algorithms, got %', got; END IF;
  SELECT COUNT(*) INTO got FROM alg_cases WHERE puzzle = '3x3' AND set_slug = 'eo4a';
  IF got <> 11 THEN RAISE EXCEPTION '3x3/eo4a: expected 11 cases, got %', got; END IF;
  SELECT COALESCE(SUM((SELECT SUM(jsonb_array_length(orientation.value)) FROM jsonb_array_elements(algs) AS orientation(value))), 0) INTO got FROM alg_cases WHERE puzzle = '3x3' AND set_slug = 'eo4a';
  IF got <> 43 THEN RAISE EXCEPTION '3x3/eo4a: expected 43 algorithms, got %', got; END IF;
  SELECT COUNT(*) INTO got FROM alg_cases WHERE puzzle = '3x3' AND set_slug = 'lse-eolr';
  IF got <> 46 THEN RAISE EXCEPTION '3x3/lse-eolr: expected 46 cases, got %', got; END IF;
  SELECT COALESCE(SUM((SELECT SUM(jsonb_array_length(orientation.value)) FROM jsonb_array_elements(algs) AS orientation(value))), 0) INTO got FROM alg_cases WHERE puzzle = '3x3' AND set_slug = 'lse-eolr';
  IF got <> 48 THEN RAISE EXCEPTION '3x3/lse-eolr: expected 48 algorithms, got %', got; END IF;
  SELECT COUNT(*) INTO got FROM alg_cases WHERE puzzle = 'pyraminx' AND set_slug = 'l3e';
  IF got <> 5 THEN RAISE EXCEPTION 'pyraminx/l3e: expected 5 cases, got %', got; END IF;
  SELECT COALESCE(SUM((SELECT SUM(jsonb_array_length(orientation.value)) FROM jsonb_array_elements(algs) AS orientation(value))), 0) INTO got FROM alg_cases WHERE puzzle = 'pyraminx' AND set_slug = 'l3e';
  IF got <> 16 THEN RAISE EXCEPTION 'pyraminx/l3e: expected 16 algorithms, got %', got; END IF;
  SELECT COUNT(*) INTO got FROM alg_cases WHERE puzzle = 'pyraminx' AND set_slug = 'l4e';
  IF got <> 49 THEN RAISE EXCEPTION 'pyraminx/l4e: expected 49 cases, got %', got; END IF;
  SELECT COALESCE(SUM((SELECT SUM(jsonb_array_length(orientation.value)) FROM jsonb_array_elements(algs) AS orientation(value))), 0) INTO got FROM alg_cases WHERE puzzle = 'pyraminx' AND set_slug = 'l4e';
  IF got <> 202 THEN RAISE EXCEPTION 'pyraminx/l4e: expected 202 algorithms, got %', got; END IF;
END
$cubingapp_roux_pyraminx_counts$;
